class RevokedSession(BaseModel):
    """
    An operator session signed out anywhere in the install. A
    verifier refuses a session whose `jti` is listed, and an
    exchanged token whose `sid` is. Pruned once `exp` has passed.

    """

    jti: str
    exp: int = Field(..., description="The session's own `exp`, unix seconds.")


class TrustBundle(BaseModel):
    """
    The set of keys every verifier in the install trusts, and what
    each may issue. Published by the control root, signed with its
    identity key, carried as the claims of `SignedTrustBundle.jws`.
    Design: `docs/design/per-node-token-keys.md`.

    **The token profile it governs.** Every token is a JWS compact
    JWT with header `{"alg": "EdDSA", "typ": <class>, "kid": <kid>}`
    and claims `iss`, `sub`, `aud` (an array), `iat`, `exp` and
    `jti`. There are three classes:

    * `ep-session+jwt`: an operator session (`sub: operator`), or a
      token obtained from one by exchange, which also carries `act`
      (`{"sub": "node:<asking machine>"}`) and `sid` (the session's
      `jti`).
    * `ep-service+jwt`: a process calling another; `sub` is the
      caller's kind.
    * `ep-client+jwt`: a key an app outside the install holds;
      `jti` is the key's id.

    Recipients are `node:<name>` (every component on that machine),
    `control` (the root), and `gateway` (the install's front door,
    for client keys only).

    **A verifier:**

    1. finds the key by `kid` in the bundle it holds, and refuses an
       unknown one;
    2. takes the algorithm from the key, never from the header;
    3. checks the signature, `exp` and `iat` with a 300 s leeway,
       `typ` against the route's classes, `iss` against the key's
       issuer, `aud` against itself, and the key's `grants` against
       what the token claims;
    4. refuses a token that lives longer than its class allows:
       1 hour for a service token to another machine, 400 days to
       the issuer's own, 14 days for a session, 10 minutes for an
       exchanged token, and 400 days for a client key;
    5. refuses a session that is listed in `revokedSessions`, or
       whose `aud` names a node no longer in the bundle.

    No hard expiry, deliberately. A bundle that stopped verifying
    when the root was dead would end the data path's guarantee to
    outlive it, so a verifier keeps the newest bundle it holds and
    its age is reported instead.

    """

    version: int = Field(
        ...,
        description="The control root's replicated log index when this bundle was\nbuilt, so it only grows, including across a promotion. A\nverifier refuses a lower version than it holds (rollback)\nand replaces its bundle with an equal or higher one.\n",
        ge=0,
    )
    epoch: int = Field(
        ..., description="The control root's epoch; an agent refuses a lower one.", ge=0
    )
    iat: int = Field(
        ...,
        description='When the bundle was signed, unix seconds. Its age is reported, never enforced.',
    )
    authority: str = Field(
        ...,
        description="Base64 of the raw 32-byte Ed25519 public key that signed this\nbundle: the control root's identity key, which every node\npins at enrollment, or a standalone agent's own identity key.\nA verifier refuses a bundle whose `authority` is not the key\nit pinned.\n",
    )
    keys: list[TrustKey]
    revokedSessions: list[RevokedSession]


class SignedTrustBundle(BaseModel):
    jws: str = Field(
        ...,
        description='A JWS compact serialization with header\n`{"alg": "EdDSA", "typ": "ep-trust-bundle+jwt"}`, whose\npayload is a `TrustBundle`, signed with the key its\n`authority` names. The signature covers the payload\'s exact\nbytes, so nothing has to be re-serialized to check it.\n',
    )


class Alg(StrEnum):
    """
    Encryption algorithm identifier.
    """

    secretbox_xsalsa20poly1305 = 'secretbox-xsalsa20poly1305'


class MasterKeyEnvelope(BaseModel):
    """
    Encrypted-at-rest envelope for sensitive config fields. The
    on-disk YAML for fields marked `sensitive: true` is stored as
    this envelope when v0.2 security is enabled; the component
    decrypts using the master key passed in by the agent at
    spawn time (env var `EUGENE_PLEXUS_<KIND>_MASTER_KEY`,
    base64-encoded).

    Algorithm: libsodium secretbox (XSalsa20-Poly1305). The nonce
    is generated per-encryption and stored alongside the
    ciphertext. The master key is 32 bytes derived from the
    operator's passphrase via Argon2id with parameters chosen at
    first-run time and persisted in the agent's state.

    Components MAY accept plaintext values in PATCH requests
    (current behavior); on persist, they encrypt to this envelope
    if the master key is available. GET requests continue to
    return `"<redacted>"` for sensitive fields regardless of
    envelope-vs-plaintext on disk.

    """

    alg: Alg = Field(..., description='Encryption algorithm identifier.')
    nonce: str = Field(
        ...,
        description='Base64-encoded 24-byte nonce. Generated per-encryption,\nnever reused with the same key.\n',
    )
    ciphertext: str = Field(..., description='Base64-encoded ciphertext + auth tag.')


class RestartResult(BaseModel):
    """
    Acknowledgement returned by `POST /v1/admin/restart`. The
    component schedules its own process exit shortly after returning
    this response (typically a few hundred ms — long enough for the
    HTTP response to flush). The component does NOT bring itself
    back up; a process supervisor (systemd, docker-compose, the
    deploy launcher, etc.) is expected to relaunch it. In v0.1
    personal-use deploys without a supervisor, the operator
    relaunches manually.

    """

    scheduled: bool = Field(
        ...,
        description='True if the component accepted the restart and an exit is\nqueued. Always true in v0.1 — the endpoint has no reason to\nrefuse — but typed as a boolean so future versions can gate\non (e.g.) an in-flight long-running operation.\n',
    )
    delayMs: int = Field(
        ...,
        description='How long the component intends to wait before calling exit,\nmeasured from the moment the response is sent. Lets clients\ntime their UI ("restarting in 0.5s…") and decide when to\nstart polling `/healthz` for the relaunched process.\n',
        ge=0,
    )
    message: str | None = Field(
        None,
        description='Optional human-readable note (e.g. "logs flushed, exiting\nnow"). UI may display this in the restart-progress dialog.\n',
    )


class ShareCredential(BaseModel):
    """
    A user name and password this host uses to reach one file server.

    **The unit is the server, not the share**, and that is a Windows
    constraint rather than a simplification: Windows refuses a second
    set of credentials to a server it already holds a session with
    (`ERROR_SESSION_CREDENTIAL_CONFLICT`, 1219), so a per-share
    credential would be a field that cannot always be honoured. One
    entry covers every share on that host.

    **Why this exists at all.** An agent that runs as a Windows
    service has no per-user credential store, so the entry a person
    once typed into Explorer is invisible to it — and at Windows 11
    defaults there is no guest fallback either
    (`EnableInsecureGuestLogons` is 0), so a share that asks for
    nobody in particular is still refused with
    *"your organization's security policies block unauthenticated
    guest access"* (measured 2026-09-18 against the live install's
    own NAS). Without this the agent comes back after a reboot
    unable to read a single model, with every health check green.

    **Per node, and that is `library-folders-and-reach`'s shape
    rather than a departure from it.** A folder states its `mounts`
    once because a mount is a property of the share; a credential is
    a property of *this machine's relationship to* the share, which
    is exactly what `pathMappings` already is. Nodes do not inherit
    credentials, and a folder never carries one.

    Nothing here is required to mount anything: the agent asks the
    OS to establish the session, and an operator who has already
    arranged access another way leaves the list empty.

    """

    host: str = Field(
        ...,
        description="The file server, as the paths that need it spell it — a host\nname or an address, with no leading slashes and no share\nname. `192.168.16.252` covers `\\\\192.168.16.252\\downloads`\nand `\\\\192.168.16.252\\appdata` both. Matched\ncase-insensitively, because a server name is.\n\nA name and an address for the same machine are **two\ndifferent servers** to Windows, which keys a session by the\nname it was dialled with. That is a tripwire worth knowing\nrather than a rule to work around: spell it here the way the\nLibrary folder's mounts spell it.\n",
    )
    username: str = Field(
        ...,
        description='The account on the file server, not on this machine.\n`DOMAIN\\user` where the server wants one.\n',
    )
    password: str | None = Field(
        None,
        description="Redacted in `GET /v1/config` exactly as a `secret` scalar is\n— the value comes back as null and the entry keeps its `host`\nand `username`, so a UI can render the row without ever\nholding the secret. A `PATCH` that omits `password` on an\nentry whose `host` already exists **keeps the stored one**,\nso editing a user name does not silently blank the password;\nan explicit empty string clears it.\n\n**At rest it is sealed with the install's master key**, the\nsame envelope a driver's `apiKey` gets, so it is not\nreadable from the config file — and so it is readable only\nonce the agent is unlocked. On a host whose `securityMode`\nis `prompt_on_startup` that means shares are not reachable\nuntil somebody signs in, which is the same thing everything\nelse behind the master key already does and is reported the\nsame way rather than failing as a missing file.\n",
    )


class PathMapping(BaseModel):
    """
    One rule for reading a path that another machine wrote.

    The library describes each model by its path **on the library's
    own host**, and a runtime declaration copies that string
    verbatim — so when the engine runs elsewhere, the agent there is
    handed a path from a filesystem it does not have. A mapping says
    where the same directory is on this host: the NAS's `/models`
    is `Z:\\models` on the Windows box that mounts it. Nothing is
    copied or cached; the operator mounts the share, and this tells
    the agent where they mounted it.

    Shared here because it appears in two places on the agent: as
    the entries of the `pathMappings` config field, and as
    `ModelLocation.mapping` on an admission answer, which reports
    the rule that applied. Two definitions of one pair would drift.

    """

    from_: str = Field(
        ...,
        alias='from',
        description="A directory as the other machine states it — in practice a\nlibrary root, spelled exactly as the library's own\n`GET /v1/config` lists it. Its shape decides how it matches:\na drive letter or UNC prefix means Windows rules (case-\ninsensitive, `/` and `\\` interchangeable); a leading `/`\nmeans POSIX rules. The agent cannot know the library's\noperating system, and the string came from it, so the\nstring stands in.\n",
    )
    to: str = Field(
        ...,
        description="The same directory on the host holding this config. Used\nverbatim, `~` expanded; the remainder of a matched path is\nre-joined onto it with this host's own separator.\n",
    )


class LibraryFolder(BaseModel):
    """
    One directory the library catalogues, and where other machines
    find it (2026-09-14).

    `path` is the directory as the library's own host spells it —
    what the scanner walks, what a `ModelSummary.path` starts with,
    the left-hand side of every rule that reaches it. `mounts` is
    the same directory as **other** machines see it: a POSIX-shaped
    entry is for Linux and macOS nodes, a Windows-shaped one (drive
    letter or UNC) for Windows nodes, and a node takes the first
    entry of its own shape. That is the whole of "how does node X
    reach folder Y" for every node that mounts the share where the
    folder says; a node that mounts it elsewhere carries one
    override in its agent's `pathMappings`, and a node with no
    mount of its shape opens `path` as written — the identical-mount
    convention, and every single-host install.

    The rule this replaces was per node per folder, on each node's
    agent, and grew as nodes × folders with every row typed by hand.
    This is per folder, stated once. Nothing is copied or cached:
    the operator mounts the share, this says where.

    """

    path: str = Field(
        ...,
        description="Absolute, as the library's host spells it. Immutable in the\nsense that changing it is a different folder: models are\nidentified by their path under it.\n",
    )
    mounts: list[str] | None = Field(
        [],
        description='Absolute paths, each Windows- or POSIX-shaped; the shape\nsays which nodes it is for. Order matters only among entries\nof one shape, where the first wins. Empty means "reached at\n`path`, or not at all".\n',
    )


